      );
    case "provider_text":
      return (
        <article className="max-w-[90%] whitespace-pre-wrap rounded-2xl rounded-bl-md border border-[var(--aria-line)] bg-[var(--aria-panel)] px-4 py-3 text-sm leading-6 shadow-sm">
          {entry.content}
        </article>
      );
