          className="rounded-xl border border-[var(--aria-danger)] bg-[var(--aria-danger-soft)] px-4 py-3 text-sm font-semibold text-[var(--aria-ink)] shadow-sm"
        >
          生成失败：{entry.content}
        </div>
      );
